for r0, c0 in sorted(test_3s):
    dist_to_top, dist_to_bottom = r0, h-1-r0
    dist_to_left, dist_to_right = c0, w-1-c0
    is_corner = (r0 <= 2 and c0 <= 2) or (r0 <= 2 and c0 >= w-2) or \
                (r0 >= h-2 and c0 <= 2) or (r0 >= h-2 and c0 >= w-2)
    apply_edge_pattern(output, r0, c0) if is_corner else apply_diamond_pattern(output, r0, c0)

